 public static class StatusUiRenderer {
  static readonly Font title=new Font("Microsoft YaHei UI",16,FontStyle.Bold,GraphicsUnit.Pixel),body=new Font("Microsoft YaHei UI",13.5f,FontStyle.Regular,GraphicsUnit.Pixel),value=new Font("Microsoft YaHei UI",13.5f,FontStyle.Bold,GraphicsUnit.Pixel),small=new Font("Microsoft YaHei UI",13,FontStyle.Regular,GraphicsUnit.Pixel),name=new Font("Microsoft YaHei UI",14,FontStyle.Bold,GraphicsUnit.Pixel);
  static readonly Color Good=Color.FromArgb(110,235,160),Warm=Color.FromArgb(255,205,90),Bad=Color.FromArgb(255,130,130);
  static void Text(Graphics g,string text,Font font,Color color,RectangleF rect,StringAlignment align){using(var b=new SolidBrush(color))using(var f=new StringFormat{FormatFlags=StringFormatFlags.NoWrap,Trimming=StringTrimming.EllipsisCharacter,Alignment=align,LineAlignment=StringAlignment.Center})g.DrawString(text??"",font,b,rect,f);}
  public static AgentTaskState TaskState(LegacySnapshot data,int index){var state=data==null||data.Activity==null?new AgentTaskState():index==0?data.Activity.Codex:data.Activity.Claude;return index==1&&state.Source=="claude-code-hooks"?new AgentTaskState():state;}
  public static Color AgentColor(AgentTaskState task,DateTimeOffset now){switch(task.Effective(now)){case "working":return Good;case "idle":return Color.FromArgb(164,211,230);case "waiting":return Warm;case "error":return Bad;default:return Color.FromArgb(213,223,233);}}
  public static Color DesktopAgentColor(LegacySnapshot data,int index,DateTimeOffset now){bool known=data!=null&&data.IsFresh(now)&&(index==0?data.CodexKnown:data.ClaudeKnown),up=data!=null&&(index==0?data.CodexRun:data.ClaudeUp);return known&&up?AgentColor(TaskState(data,index),now):Color.FromArgb(213,223,233);}
  public static string DesktopAgentLabel(LegacySnapshot data,int index,DateTimeOffset now,bool compact){bool known=data!=null&&data.IsFresh(now)&&(index==0?data.CodexKnown:data.ClaudeKnown),up=data!=null&&(index==0?data.CodexRun:data.ClaudeUp);if(!known)return compact?"未知":"应用状态未知";if(!up)return "未运行";var task=TaskState(data,index);return task.Fresh(now)&&task.Effective(now)!="offline"?task.Label(now):(index==0?"状态不可用":"在线");}
  public static bool DesktopAgentWorking(LegacySnapshot data,int index,DateTimeOffset now){return data!=null&&data.IsFresh(now)&&(index==0?data.CodexKnown&&data.CodexRun:data.ClaudeKnown&&data.ClaudeUp)&&TaskState(data,index).Effective(now)=="working";}
  public static string DesktopAgentHint(LegacySnapshot data,int index,DateTimeOffset now){var task=TaskState(data,index);string title=index==0?"Codex 桌面":"Claude 桌面",label=DesktopAgentLabel(data,index,now,false);if(task.Source=="codex-file-activity-estimate"&&task.Fresh(now))return title+"："+label+"（根据近期文件活动估计）";if(label=="在线"||label=="状态不可用")return title+"：在线。暂时无法获取任务状态。";if(label=="未运行")return title+"：未检测到桌面应用。";if(label=="应用状态未知")return title+"：暂时无法确认应用状态。";return title+"："+label+" · 已验证的任务事件";}
  public static Bitmap RenderLive(int width,int height,int margin,LegacySnapshot snapshot,int page,double phase){var frame=new StatusFrameData(snapshot,page,phase);return Render(width,height,margin,frame.Snapshot,frame.Current,frame.Next,frame.Phase);}
  static Color MetricColor(double? n,bool fresh){return !fresh||!n.HasValue||n<0||n>100||Double.IsNaN(n.Value)||Double.IsInfinity(n.Value)?Palette.Secondary:n>=90?Bad:n>=75?Warm:Good;}
  static string Number(double? n,bool fresh){return !fresh||!n.HasValue||Double.IsNaN(n.Value)||Double.IsInfinity(n.Value)||n<0||n>100?"\u2014":Math.Max(0,Math.Min(100,n.Value)).ToString("0.0")+"%";}
  static void Dot(Graphics g,float x,float y,Color color){using(var b=new SolidBrush(color))g.FillEllipse(b,x,y,5,5);}
  public static Bitmap Render(int width,int height,int margin,LegacySnapshot data,string ticker){return Render(width,height,margin,data,ticker,null,0);}
  public static Bitmap Render(int width,int height,int margin,LegacySnapshot data,string ticker,string next,double phase){var image=GlassSurface.StatusBackground(width,height,margin,height<232?37:24);using(var g=Graphics.FromImage(image)){g.TranslateTransform(margin,margin);g.SmoothingMode=SmoothingMode.AntiAlias;g.TextRenderingHint=System.Drawing.Text.TextRenderingHint.AntiAliasGridFit;using(var clip=GlassSurface.Path(new RectangleF(0,0,width,height),height<232?37:24))g.SetClip(clip);bool fresh=data!=null&&data.IsFresh(DateTimeOffset.UtcNow);var muted=SystemInformation.HighContrast?SystemColors.WindowText:Color.FromArgb(234,240,246);var text=Palette.Text;
   StatusSignal.From(data).Paint(g,width,height);if(height<232){StatusPerformance.PaintTicker(g,new RectangleF(27,7,width-75,23),body,text,ticker,next,phase);for(int i=0;i<2;i++){var icon=StatusUiLayout.ServiceIcon(i,width,height);bool known=data!=null&&(i==0?data.CodexKnown:data.ClaudeKnown),up=data!=null&&(i==0?data.CodexRun:data.ClaudeUp);int slot=Math.Max(1,(width-54)/2);var task=TaskState(data,i);Text(g,(i==0?"Codex":"Claude")+" · "+DesktopAgentLabel(data,i,DateTimeOffset.UtcNow,height<232),small,text,new RectangleF(icon.Right+6,36,slot-39,22),StringAlignment.Near);Dot(g,icon.Left+slot-14,45,DesktopAgentColor(data,i,DateTimeOffset.UtcNow));}}
   else{Text(g,"\u72b6\u6001\u53f0",title,text,StatusUiLayout.HeaderTitle(width),StringAlignment.Near);StatusPerformance.PaintTicker(g,StatusUiLayout.HeaderTicker(width),small,muted,ticker,next,phase);using(var p=new Pen(Color.FromArgb(24,255,255,255)))g.DrawLine(p,20,61,width-20,61);
    var numbers=data==null?new double?[]{null,null,null,null}:new[]{data.Cpu,data.Memory,data.DiskD,data.Gpu};string[] labels={"CPU Utility","\u5185\u5b58","\u786c\u76d8 D","GPU · NVIDIA"};for(int i=0;i<4;i++){var r=StatusUiLayout.Metric(i,width);Text(g,labels[i],body,muted,new RectangleF(r.X,r.Y,r.Width-94,18),StringAlignment.Near);string metric=Number(numbers[i],fresh);if(i==3&&fresh&&data.GpuUsedMb.HasValue&&data.GpuTotalMb.HasValue)metric+="  "+(data.GpuUsedMb.Value/1024).ToString("0.0")+"/"+(data.GpuTotalMb.Value/1024).ToString("0.#")+" GiB";Text(g,metric,value,MetricColor(numbers[i],fresh),new RectangleF(r.Right-168,r.Y,168,18),StringAlignment.Far);var track=new RectangleF(r.Left,r.Top+23,r.Width,3);using(var p=GlassSurface.Path(track,1.5f))using(var b=new SolidBrush(Color.FromArgb(24,255,255,255)))g.FillPath(b,p);if(fresh&&numbers[i].HasValue&&numbers[i]>=0&&numbers[i]<=100&&!Double.IsNaN(numbers[i].Value)){float fill=(float)(r.Width*Math.Max(0,Math.Min(100,numbers[i].Value))/100);if(fill>1)using(var p=GlassSurface.Path(new RectangleF(track.X,track.Y,fill,3),1.5f))using(var b=new SolidBrush(MetricColor(numbers[i],fresh)))g.FillPath(b,p);}}
    for(int i=0;i<2;i++){var r=StatusUiLayout.Service(i,width);bool known=data!=null&&(i==0?data.CodexKnown:data.ClaudeKnown),up=data!=null&&(i==0?data.CodexRun:data.ClaudeUp);using(var p=GlassSurface.Path(r,16))using(var b=new SolidBrush(Color.FromArgb(12,255,255,255)))g.FillPath(b,p);Text(g,i==0?"Codex":"Claude",name,known&&up?text:muted,new RectangleF(r.Left+51,r.Top+18,r.Width-59,25),StringAlignment.Near);var task=TaskState(data,i);Dot(g,r.Right-17,r.Top+12,DesktopAgentColor(data,i,DateTimeOffset.UtcNow));Text(g,DesktopAgentLabel(data,i,DateTimeOffset.UtcNow,height<232),small,muted,new RectangleF(r.Left+10,r.Top+46,r.Width-20,18),StringAlignment.Center);}
    var net=data==null?new NetworkReadonlySnapshot():data.Network;var route=StatusUiLayout.Connection(0,width);Text(g,"网站耗时",small,muted,new RectangleF(route.X,route.Y,80,19),StringAlignment.Near);string current=WebsiteLatency.Label(DateTimeOffset.UtcNow);Text(g,current,small,text,new RectangleF(route.X+85,route.Y,Math.Max(1,route.Width-137),19),StringAlignment.Far);using(var buttonPath=GlassSurface.Path(new RectangleF(route.Right-43,route.Y,43,19),8))using(var buttonFill=new SolidBrush(Color.FromArgb(18,255,255,255)))using(var buttonEdge=new Pen(Color.FromArgb(55,255,255,255),1)){g.FillPath(buttonFill,buttonPath);g.DrawPath(buttonEdge,buttonPath);}Text(g,"测速",small,text,new RectangleF(route.Right-43,route.Y,43,19),StringAlignment.Center);
    var balance=StatusUiLayout.Connection(1,width);Text(g,"DeepSeek",small,muted,new RectangleF(balance.X,balance.Y,120,19),StringAlignment.Near);var account=data==null?new BalanceReadonlySnapshot():data.Balance;Text(g,account.Label(DateTimeOffset.UtcNow),small,account.Fresh(DateTimeOffset.UtcNow)?account.Available?Good:Warm:muted,new RectangleF(balance.X+125,balance.Y,balance.Width-125,19),StringAlignment.Far);
    for(int i=0;i<2;i++){var r=StatusUiLayout.Voice(i,width);using(var p=GlassSurface.Path(r,9))using(var b=new SolidBrush(Color.FromArgb(15,255,255,255)))g.FillPath(b,p);string pack=data==null?"":i==0?data.CodexVoice:data.ClaudeVoice;Text(g,VoicePackStore.Label(pack),small,data!=null&&data.VoiceAvailable?text:muted,new RectangleF(r.X+7,r.Y,r.Width-14,r.Height),StringAlignment.Center);}
   }g.ResetTransform();StatusDockState.PaintCollapse(g,width,margin);
  }return image;}
 }
